204→		TargetInfo:      c.targetInfo(),
205→		Version: Version{
206→			// 宣告一个通用的现代版本号，只影响客户端的展示与兼容分支。
207→			Major: 6, Minor: 1, Build: 7601, NTLMRevision: NTLMRevisionCurrent,
208→		},
209→	}
210→	c.challengeMsg = ch.Marshal()
211→	return c.wrap(NegAcceptIncomplete, c.challengeMsg, nil), false, nil
212→}
213→
214→// challengeFlags 计算 CHALLENGE 里回给客户端的协商标志。
215→//
216→// 原则：只保留双方都支持的位，并强制打开 NTLMv2 必需的
217→// EXTENDED_SESSIONSECURITY / TARGET_INFO / ALWAYS_SIGN。
218→func (c *ntlmContext) challengeFlags(client NegotiateFlags) NegotiateFlags {
219→	f := NegotiateNTLM |
220→		NegotiateRequestTarget |
221→		NegotiateTargetTypeServer |
222→		NegotiateTargetInfo |
223→		NegotiateAlwaysSign |
224→		NegotiateExtendedSessionSecurity |
225→		NegotiateVersion |
226→		Negotiate128 |
227→		Negotiate56
228→
229→	// 字符集：优先 Unicode。
230→	if client.Has(NegotiateUnicode) || !client.Has(NegotiateOEM) {
231→		f |= NegotiateUnicode
232→	} else {
233→		f |= NegotiateOEM
234→	}
235→
236→	// 这些位必须**镜像客户端的请求**，否则密钥协商会不一致。
237→	for _, bit := range []NegotiateFlags{
238→		NegotiateSign, NegotiateSeal, NegotiateKeyExch, NegotiateIdentify,
239→	} {
240→		if client.Has(bit) {
241→			f |= bit
242→		}
243→	}
244→	return f
245→}
246→
247→// targetInfo 构造 CHALLENGE 的 TargetInfo。
248→//
249→// MS-NLMP §2.2.2.1：前四项（NbDomainName / NbComputerName /
250→// DnsDomainName / DnsComputerName）不全时部分 Windows 客户端会拒绝，
251→// 因此一律带齐，并附上 Timestamp（NTLMv2 需要它来做重放窗口判断）。
252→func (c *ntlmContext) targetInfo() AvPairs {
253→	o := &c.p.opts
254→	return AvPairs{
255→		{ID: MsvAvNbDomainName, Value: utf16le(o.DomainName)},
256→		{ID: MsvAvNbComputerName, Value: utf16le(o.ServerName)},
257→		{ID: MsvAvDnsDomainName, Value: utf16le(o.DNSDomainName)},
258→		{ID: MsvAvDnsComputerName, Value: utf16le(o.DNSComputerName)},
259→		{ID: MsvAvTimestamp, Value: encodeFiletime(filetimeNow(o.Now()))},
260→	}
261→}
262→
263→// handleAuthenticate 处理 Type 3，完成校验。
264→func (c *ntlmContext) handleAuthenticate(msg []byte) ([]byte, bool, error) {
265→	m, err := ParseAuthenticateMessage(msg)
266→	if err != nil {
267→		return nil, false, err
268→	}
269→	if c.challengeMsg == nil {
270→		// 没发过 CHALLENGE 就收到 AUTHENTICATE，状态机被跳步。
271→		return nil, false, ErrInvalidToken
272→	}
273→
274→	if m.IsAnonymous() {
275→		if !c.p.opts.AllowAnonymous {
276→			return nil, false, ErrLogonFailure
277→		}
278→		c.identity = &Identity{Workstation: m.Workstation, Anonymous: true}
279→		c.sessionKey = make([]byte, SessionKeyLen)
280→		c.done = true
281→		return c.wrap(NegAcceptCompleted, nil, nil), true, nil
282→	}
283→
284→	acct, lookupErr := c.lookup(m.UserName, m.DomainName)
285→
286→	// 用户不存在时也走一遍等价耗时的校验，避免用户枚举（provider.go 的要求）。
287→	ntHash := acct.NTHash
288→	ntowf := NTOWFv2(ntHash, m.UserName, m.DomainName)
289→	sbk, blob, ok := VerifyNTLMv2(ntowf, c.serverChallenge, m.NTResponse)
290→	if lookupErr != nil {
291→		ok = false
292→	}
293→
294→	if !ok {
295→		if c.p.opts.Store != nil && c.p.opts.Store.AllowGuest() {
296→			// 降级为 guest：没有可用的 session key，会话不能签名。
297→			c.identity = &Identity{
298→				User:        m.UserName,
299→				Domain:      m.DomainName,
300→				Workstation: m.Workstation,
301→				Guest:       true,
302→			}
303→			c.sessionKey = make([]byte, SessionKeyLen)
304→			c.done = true
305→			return c.wrap(NegAcceptCompleted, nil, nil), true, nil
306→		}
307→		return nil, false, ErrLogonFailure
308→	}
309→
310→	esk, err := ExportedSessionKey(KeyExchangeKey(sbk), m.Flags, m.EncryptedRandomSessionKey)
311→	if err != nil {
312→		return nil, false, err
313→	}
314→
315→	if err := c.verifyMIC(m, blob, esk); err != nil {
316→		return nil, false, err
317→	}
318→
319→	// mechListMIC 必须在确立 identity 之前校验：它防的是中间人篡改 SPNEGO
320→	// 机制列表做降级，校验不过等同于认证失败。
321→	mic, err := c.spnegoMIC(esk, m.Flags)
322→	if err != nil {
323→		return nil, false, err
324→	}
325→
326→	c.identity = &Identity{
327→		User:        acct.User,
328→		Domain:      m.DomainName,
329→		Workstation: m.Workstation,
330→		UID:         acct.UID,
331→		GID:         acct.GID,
332→	}
333→	c.sessionKey = append([]byte(nil), esk[:]...)
334→	c.done = true
335→
336→	return c.wrap(NegAcceptCompleted, nil, mic), true, nil
337→}
338→
339→// spnegoMIC 校验客户端的 mechListMIC 并生成服务端自己的（RFC 4178 §5）。
340→//
341→// 计算输入是**客户端 negTokenInit 里 MechTypeList 的完整 DER**
342→// （含外层 SEQUENCE 的 tag 与 length），不是里面几个 OID 的裸拼接 ——
343→// RFC 4178 §5 对此写得含糊，这里以 Windows / Samba 的实际行为为准。
344→//
345→// 已用 smbclient（Samba 4，-m SMB3，signing required）实测抓包比对：
346→//
347→//	mechTypeList DER   30 0c 06 0a 2b 06 01 04 01 82 37 02 02 0a
348→//	客户端 mechListMIC 01 00 00 00 d8 74 4b c1 89 2b 8d f0 00 00 00 00
349→//	服务端 mechListMIC 01 00 00 00 1b 17 e7 47 b3 7d a8 e0 00 00 00 00
350→//
351→// 两个方向各用一个独立的 NTLM 会话安全状态，序号都从 0 开始：
352→// mechListMIC 是各自方向上第一次、也是唯一一次 GSS_GetMIC
353→// （认证完成后 SMB2 改用自己派生的签名密钥，不再走 NTLM 的 MAC）。
354→//
355→// 返回服务端要放进最终 negTokenResp 的 mechListMIC；不需要时为 nil。
356→func (c *ntlmContext) spnegoMIC(esk [16]byte, flags NegotiateFlags) ([]byte, error) {
357→	// 裸 NTLMSSP 没有 SPNEGO 外壳，客户端也没发过 mechTypes，无从计算。
358→	if !c.spnego || len(c.clientMechListDER) == 0 {
359→		return nil, nil
360→	}
361→	// 没协商 extended session security 就没有 SignKey（MS-NLMP §3.4.5.2），
362→	// 这类老客户端本来也不会发 mechListMIC。
363→	if !flags.Has(NegotiateExtendedSessionSecurity) {
364→		return nil, nil
365→	}
366→	// 客户端没带 MIC 时不能强制要求（老客户端不发），
367→	// 也不主动回一个 —— RFC 4178 §5 是"对端发了才回"的对称语义。
368→	if len(c.clientMechListMIC) == 0 {
369→		return nil, nil
370→	}
371→
372→	// 校验方向：客户端是发送方，用 client-to-server 的 SigningKey。
373→	cc, err := NewSigningContext(esk[:], flags, true)
374→	if err != nil {
375→		return nil, err
376→	}
377→	want := cc.MIC(c.clientMechListDER)
378→	if subtle.ConstantTimeCompare(want[:], c.clientMechListMIC) != 1 {
379→		return nil, ErrLogonFailure
380→	}
381→
382→	// 生成方向：服务端是发送方，用 server-to-client 的 SigningKey。
383→	sc, err := NewSigningContext(esk[:], flags, false)
384→	if err != nil {
385→		return nil, err
386→	}
387→	out := sc.MIC(c.clientMechListDER)
388→	return out[:], nil
389→}
390→
391→// dummyAccount 用于用户不存在时的等时校验，NTHash 恒为零值。
392→var dummyAccount = &Account{}
393→
394→func (c *ntlmContext) lookup(user, domain string) (*Account, error) {
395→	if c.p.opts.Store == nil {
396→		return dummyAccount, ErrNoSuchUser
397→	}
398→	acct, err := c.p.opts.Store.Lookup(user, domain)
399→	if err != nil || acct == nil {
400→		return dummyAccount, ErrNoSuchUser
401→	}
402→	return acct, nil
403→}
404→
405→// verifyMIC 在客户端声明带 MIC 时校验它（MS-NLMP §3.2.5.1.2）。
406→//
407→// MsvAvFlags 的 0x00000002 位置位表示 AUTHENTICATE_MESSAGE 里有 MIC，
408→// 此时服务端**必须**校验，否则中间人可以篡改 NEGOTIATE 里的标志位降级。
409→func (c *ntlmContext) verifyMIC(m *AuthenticateMessage, blob []byte, esk [16]byte) error {
410→	// blob 布局（MS-NLMP §2.2.2.7 NTLMv2_CLIENT_CHALLENGE）：
411→	// RespType(1) HiRespType(1) Z(2) Z(4) Timestamp(8) ClientChallenge(8) Z(4) AvPairs
412→	const clientChallengeHeader = 28
413→	if len(blob) < clientChallengeHeader {
414→		return nil // 不是 NTLMv2 blob（LMv2-only 之类），没有 AV_PAIR 可看
415→	}
416→	avs, err := ParseAvPairs(blob[clientChallengeHeader:])
417→	if err != nil {
418→		return ErrInvalidToken
419→	}
420→	v, ok := avs.Get(MsvAvFlags)
421→	if !ok || len(v) < 4 {
422→		return nil
423→	}
424→	flags := uint32(v[0]) | uint32(v[1])<<8 | uint32(v[2])<<16 | uint32(v[3])<<24
425→	if flags&AvFlagMICPresent == 0 {
426→		return nil
427→	}
428→	if !m.MICPresent {
429→		// 声明有 MIC 却没有字段 —— 拒绝，不能当作没带处理。
430→		return ErrLogonFailure
431→	}
432→	want := ComputeMIC(esk, c.negotiateMsg, c.challengeMsg, m.rawWithZeroMIC())
433→	if subtle.ConstantTimeCompare(want[:], m.MIC[:]) != 1 {
434→		return ErrLogonFailure
435→	}
436→	return nil
437→}
438→
439→// ServerChallenge 返回本次握手使用的 8 字节服务端质询（供日志/测试）。
440→func (c *ntlmContext) ServerChallenge() [8]byte { return c.serverChallenge }
441→

