  5→
  6→	"github.com/finalappstore/stupidsamba/internal/smb/crypto"
  7→	"github.com/finalappstore/stupidsamba/internal/smb/status"
  8→	"github.com/finalappstore/stupidsamba/internal/smb/wire"
  9→)
 10→
 11→// Handler 处理一条 SMB2 请求。
 12→//
 13→// 约定：
 14→//   - 成功时把**报文体**追加到 ctx.Out（响应头已由分发器预置），返回 nil；
 15→//   - 失败时返回 error。返回 status.Status 可以精确指定 NTSTATUS，
 16→//     返回其它错误由 status.FromVFSError 统一映射（AGENTS.md §5 P5，
 17→//     禁止在 handler 里裸写魔数）。
 18→//   - 需要返回带响应体的非 SUCCESS 状态（如 SESSION_SETUP 的
 19→//     STATUS_MORE_PROCESSING_REQUIRED、QUERY_INFO 的 STATUS_BUFFER_OVERFLOW）时，
 20→//     直接设置 ctx.Status 并返回 nil。
 21→type Handler func(ctx *Context) error
 22→
 23→// handlerSpec 描述一个命令的处理器及其前置条件。
 24→type handlerSpec struct {
 25→	fn Handler
 26→	// needSession 表示必须有一个**已认证**的会话。
 27→	needSession bool
 28→	// needTree 表示必须有一个有效的树连接。
 29→	needTree bool
 30→	// noResponse 表示本命令**永不产生响应**。
 31→	//
 32→	// 目前只有 SMB2 CANCEL（MS-SMB2 §3.3.5.16）。这类命令跳过全部前置
 33→	// 检查直接执行 handler，且不参与 credit 记账 —— 客户端收不到响应就
 34→	// 拿不回 credit，在这里扣减会让双方水位永久错位。
 35→	noResponse bool
 36→}
 37→
 38→// handlers 是命令分发表（AGENTS.md §5 P2 策略模式）。
 39→//
 40→// 新增一个命令只需要在自己的文件里 init() 调 register()，
 41→// **不需要改动本文件**。未注册的命令统一走 defaultHandler。
 42→var handlers = map[wire.Command]handlerSpec{}
 43→
 44→// register 登记一个命令处理器。重复注册会 panic —— 这是编码错误，
 45→// 发生在进程启动阶段（init），不会影响运行中的服务。
 46→func register(cmd wire.Command, needSession, needTree bool, fn Handler) {
 47→	if _, dup := handlers[cmd]; dup {
 48→		panic(fmt.Sprintf("command: %s 重复注册", cmd))
 49→	}
 50→	handlers[cmd] = handlerSpec{fn: fn, needSession: needSession, needTree: needTree}
 51→}
 52→
 53→// registerNoResponse 登记一个**不产生响应**的命令处理器（见 handlerSpec.noResponse）。
 54→func registerNoResponse(cmd wire.Command, fn Handler) {
 55→	if _, dup := handlers[cmd]; dup {
 56→		panic(fmt.Sprintf("command: %s 重复注册", cmd))
 57→	}
 58→	handlers[cmd] = handlerSpec{fn: fn, noResponse: true}
 59→}
 60→
 61→// Registered 报告某个命令是否已经实现，用于日志与测试。
 62→func Registered(cmd wire.Command) bool {
 63→	_, ok := handlers[cmd]
 64→	return ok
 65→}
 66→
 67→// NoResponse 报告某个命令是否永不产生响应（MS-SMB2 §3.3.5.16 的 CANCEL）。
 68→//
 69→// internal/server 用它决定是否要为这条消息记 credit 账。
 70→func NoResponse(cmd wire.Command) bool {
 71→	return handlers[cmd].noResponse
 72→}
 73→
 74→// defaultHandler 处理所有未实现的命令（AGENTS.md §5 P2）。
 75→func defaultHandler(ctx *Context) error {
 76→	ctx.Log.Debug("未实现的 SMB2 命令", "command", ctx.Header.Command.String(),
 77→		"remote", ctx.Conn.RemoteAddr)
 78→	return status.NotSupported
 79→}
 80→
 81→// Dispatch 处理一条请求并把响应写入 ctx.Out。
 82→//
 83→// 无论成功失败都会产生一条格式正确的响应 —— SMB2 不允许对请求静默不答，
 84→// 客户端会一直等到超时。
 85→func Dispatch(ctx *Context) {
 86→	// 不产生响应的命令（SMB2 CANCEL）在这里短路：它连一条 ERROR Response
 87→	// 都不能回 —— 那条响应的 MessageId 与被取消的请求相同，客户端会把它
 88→	// 错配成被取消请求的应答（MS-SMB2 §3.3.5.16）。
 89→	//
 90→	// 也正因为如此，这里**刻意跳过**会话定位与验签：验签失败同样不能回
 91→	// 错误响应，只能丢弃。handler 自己不信任任何前置状态。
 92→	if spec, ok := handlers[ctx.Header.Command]; ok && spec.noResponse {
 93→		_ = spec.fn(ctx)
 94→		ctx.suppress = true
 95→		ctx.discard()
 96→		return
 97→	}
 98→
 99→	err := dispatch(ctx)
100→	if err != nil {
101→		ctx.fail(status.FromVFSError(err))
102→	}
103→	ctx.finishHeader()
104→
105→	// 把本条解析/新建出的会话与树记入链，供后续 related 消息继承。
106→	if ctx.Session != nil {
107→		ctx.Chain.Session = ctx.Session
108→	}
109→	if ctx.Tree != nil {
110→		ctx.Chain.Tree = ctx.Tree
111→	}
112→
113→	// 只有 handler **真的失败**才中断复合链。
114→	// 带响应体的非 SUCCESS 状态（SESSION_SETUP 的 MORE_PROCESSING_REQUIRED、
115→	// QUERY_INFO 的 BUFFER_OVERFLOW）不算失败，后续 related 消息照常执行。
116→	if err != nil {
117→		ctx.Chain.Failed = true
118→		if ctx.Chain.FailStatus == 0 {
119→			ctx.Chain.FailStatus = ctx.Status
120→		}
121→	}
122→}
123→
124→// DispatchFailed 在前置检查（如签名校验）就已经判定失败时，
125→// 直接产生一条 ERROR Response 并回填响应头。
126→//
127→// 与 Dispatch 一样，它保证一定会写出一条格式正确的响应。
128→func DispatchFailed(ctx *Context, st status.Status) {
129→	ctx.fail(st)
130→	ctx.finishHeader()
131→	ctx.Chain.Failed = true
132→	if ctx.Chain.FailStatus == 0 {
133→		ctx.Chain.FailStatus = st
134→	}
135→}
136→
137→// dispatch 执行前置检查与 handler。
138→func dispatch(ctx *Context) error {
139→	// 复合链中前序已失败：后续 related 消息必须直接失败，不得执行
140→	// （MS-SMB2 §3.3.5.2.7）。
141→	if ctx.Header.IsRelated() && ctx.Chain.Failed {
142→		st := ctx.Chain.FailStatus
143→		if st == 0 {
144→			st = status.Unsuccessful
145→		}
146→		return st
147→	}
148→
149→	spec, ok := handlers[ctx.Header.Command]
150→	if !ok {
151→		spec = handlerSpec{fn: defaultHandler}
152→	}
153→
154→	// 先定位会话与树（含 related 继承），再校验签名 —— 验签需要会话密钥。
155→	if err := ctx.resolve(); err != nil {
156→		return err
157→	}
158→	if err := ctx.checkSignature(); err != nil {
159→		return err
160→	}
161→
162→	if spec.needSession {
163→		if ctx.Session == nil {
164→			return status.UserSessionDeleted
165→		}
166→		if !ctx.Session.Established() {
167→			return status.AccessDenied
168→		}
169→	}
170→	if spec.needTree && ctx.Tree == nil {
171→		return status.NetworkNameDeleted
172→	}
173→
174→	return spec.fn(ctx)
175→}
176→
177→// resolve 根据请求头定位会话与树，并处理复合链里的继承语义。
178→//
179→// MS-SMB2 §3.3.5.2.7：置了 SMB2_FLAGS_RELATED_OPERATIONS 的消息复用
180→// 前一条的 SessionId / TreeId，头里的对应字段应当被忽略。
181→func (c *Context) resolve() error {
182→	if c.Header.IsRelated() {
183→		c.Session = c.Chain.Session
184→		c.Tree = c.Chain.Tree
185→		// 响应头要回填真实的 Id，客户端据此对账。
186→		if c.Session != nil {
187→			c.RespHeader.SessionID = c.Session.ID
188→		}
189→		if c.Tree != nil {
190→			c.RespHeader.TreeID = c.Tree.ID
191→		}
192→		return nil
193→	}
194→
195→	if id := c.Header.SessionID; id != 0 {
196→		s := c.Conn.Session(id)
197→		if s == nil {
198→			// MS-SMB2 §3.3.5.2.9：找不到会话回 STATUS_USER_SESSION_DELETED。
199→			return status.UserSessionDeleted
200→		}
201→		c.Session = s
202→		c.Chain.Session = s
203→	}
204→
205→	if id := c.Header.TreeID; id != 0 {
206→		if c.Session == nil {
207→			return status.UserSessionDeleted
208→		}
209→		t := c.Session.Tree(id)
210→		if t == nil {
211→			// MS-SMB2 §3.3.5.2.11：找不到树回 STATUS_NETWORK_NAME_DELETED。
212→			return status.NetworkNameDeleted
213→		}
214→		c.Tree = t
215→		c.Chain.Tree = t
216→	}
217→	return nil
218→}
219→
220→// checkSignature 校验请求签名，并决定响应是否需要签名。
221→//
222→// MS-SMB2 §3.3.5.2.4：
223→//   - 请求置了 SMB2_FLAGS_SIGNED 且会话已建立 → 必须验签，失败回
224→//     STATUS_ACCESS_DENIED；
225→//   - 会话要求签名而请求没签 → STATUS_ACCESS_DENIED；
226→//   - 验签通过的请求，其响应也必须签名。
227→//
228→// SESSION_SETUP 是例外：认证完成前还没有会话密钥，签名由该命令的 handler
229→// 在密钥派生之后自行处理（§3.3.5.5.3）。
230→func (c *Context) checkSignature() error {
231→	if c.Header.Command == wire.CommandSessionSetup {
232→		return nil
233→	}
234→
235→	s := c.Session
236→	if s == nil || !s.Established() {
237→		return nil
238→	}
239→
240→	key := s.SigningKey()
241→	signed := c.Header.IsSigned()
242→
243→	if !signed {
244→		if s.SigningRequired() {
245→			c.Log.Warn("会话要求签名但请求未签名",
246→				"command", c.Header.Command.String(), "session", s.ID)
247→			return status.AccessDenied
248→		}
249→		return nil
250→	}
251→
252→	if len(key) == 0 {
253→		// 客户端声称签了名，但我们没有密钥可校验 —— 只能拒绝。
254→		return status.AccessDenied
255→	}
256→	if err := crypto.VerifyWith(c.Conn.SigningAlg(), key, c.Msg); err != nil {
257→		c.Log.Warn("请求签名校验失败",
258→			"command", c.Header.Command.String(), "session", s.ID, "err", err)
259→		return status.AccessDenied
260→	}
261→
262→	// 验签通过：响应也要签名。实际计算由 internal/server 在复合链拼装完成
263→	// 之后统一执行（签名范围含尾部对齐填充）。
264→	c.SignKey = key
265→	return nil
266→}
267→
268→// fail 丢弃已写入的响应体，改写成一条 SMB2 ERROR Response。
269→func (c *Context) fail(st status.Status) {
270→	if st == status.Success {
271→		st = status.Unsuccessful
272→	}
273→	c.ResetBody()
274→	c.Status = st
275→
276→	// MS-SMB2 §2.2.2：ByteCount 为 0 时 ErrorData 必须补 1 字节占位，
277→	// 这由 wire.ErrorResponse.Append 负责。
278→	out, err := (&wire.ErrorResponse{}).Append(c.Out)
279→	if err != nil {
280→		// ErrorResponse 是定长结构，编码不可能失败；真出错也不能让连接静默，
281→		// 保底写一条最小 ERROR body。
282→		c.Log.Error("编码 ERROR Response 失败", "err", err)
283→		c.ResetBody()
284→		c.Out = append(c.Out, 0x09, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00)
285→		return
286→	}
287→	c.Out = out
288→}
289→

