  1→package wire
  2→
  3→import (
  4→	"encoding/binary"
  5→	"errors"
  6→	"fmt"
  7→	"math"
  8→)
  9→
 10→// 解码错误。所有 Decode 方法在输入不可信时都必须返回 error 而不是 panic。
 11→var (
 12→	// ErrTruncated 表示缓冲区长度不足以容纳所需字段。
 13→	ErrTruncated = errors.New("smb2 wire: 报文被截断")
 14→	// ErrStructureSize 表示 StructureSize 字段与规范固定值不符。
 15→	ErrStructureSize = errors.New("smb2 wire: StructureSize 非法")
 16→	// ErrInvalidOffset 表示 Offset/Length 组合越界或溢出。
 17→	ErrInvalidOffset = errors.New("smb2 wire: Offset/Length 越界")
 18→	// ErrProtocolID 表示 ProtocolId 魔数不匹配。
 19→	ErrProtocolID = errors.New("smb2 wire: ProtocolId 非法")
 20→	// ErrMalformed 表示报文结构自相矛盾。
 21→	ErrMalformed = errors.New("smb2 wire: 报文格式错误")
 22→)
 23→
 24→// le 是 SMB2 报文体统一使用的字节序：**小端**（MS-SMB2 §2.1）。
 25→// 唯一的例外是 Direct TCP 的 4 字节长度前缀（大端），那在传输层处理。
 26→var le = binary.LittleEndian
 27→
 28→// need 校验 b 至少有 n 字节，避免裸切片 panic。
 29→func need(b []byte, n int) error {
 30→	if n < 0 || len(b) < n {
 31→		return fmt.Errorf("%w: 需要 %d 字节, 实际 %d", ErrTruncated, n, len(b))
 32→	}
 33→	return nil
 34→}
 35→
 36→// sliceAt 从 b 中安全取出 [off, off+length) 区间。
 37→//
 38→// off/length 来自网络，可能是任意 uint32，因此全程用 uint64 运算，
 39→// 先判溢出与越界再切片（AGENTS.md §8）。
 40→func sliceAt(b []byte, off, length uint64) ([]byte, error) {
 41→	if length == 0 {
 42→		// 长度为 0 时 offset 允许是任意值（很多客户端填 0 或填结构尾部），
 43→		// 直接返回空切片。
 44→		return nil, nil
 45→	}
 46→	end := off + length
 47→	if end < off { // uint64 回绕
 48→		return nil, fmt.Errorf("%w: off=%d length=%d 溢出", ErrInvalidOffset, off, length)
 49→	}
 50→	if end > uint64(len(b)) {
 51→		return nil, fmt.Errorf("%w: off=%d length=%d 超出缓冲区 %d", ErrInvalidOffset, off, length, len(b))
 52→	}
 53→	return b[off:end], nil
 54→}
 55→
 56→// checkStructureSize 校验结构体首 2 字节的 StructureSize 是否等于 want。
 57→//
 58→// 注意 SMB2 的坑：**可变长结构的 StructureSize 是"固定部分大小 + 1"**
 59→// （例如 CREATE Request 是 57 而非 56），want 传规范里写的那个值即可。
 60→func checkStructureSize(b []byte, want uint16) error {
 61→	if err := need(b, 2); err != nil {
 62→		return err
 63→	}
 64→	if got := le.Uint16(b); got != want {
 65→		return fmt.Errorf("%w: 期望 %d, 实际 %d", ErrStructureSize, want, got)
 66→	}
 67→	return nil
 68→}
 69→
 70→// grow 在 dst 尾部扩展 n 字节并返回 (新切片, 新增区间的子切片)。
 71→// 新增区间已清零，便于直接按偏移写字段。
 72→func grow(dst []byte, n int) ([]byte, []byte) {
 73→	base := len(dst)
 74→	if cap(dst)-base >= n {
 75→		dst = dst[:base+n]
 76→		clear(dst[base:])
 77→	} else {
 78→		dst = append(dst, make([]byte, n)...)
 79→	}
 80→	return dst, dst[base:]
 81→}
 82→
 83→// align8 返回 v 向上取整到 8 的倍数。SMB2 中 NegotiateContext、
 84→// CreateContext、目录条目链都要求 8 字节对齐。
 85→func align8(v int) int { return (v + 7) &^ 7 }
 86→
 87→// padTo8 在 dst 尾部补 0 直到相对 base 的长度是 8 的倍数。
 88→// base 通常是某个结构体在整条消息中的起点。
 89→func padTo8(dst []byte, base int) []byte {
 90→	n := align8(len(dst)-base) - (len(dst) - base)
 91→	if n > 0 {
 92→		dst, _ = grow(dst, n)
 93→	}
 94→	return dst
 95→}
 96→
 97→// u16 安全地把 int 转成 uint16，超界返回错误（防止编码时字段回绕）。
 98→func u16(n int, what string) (uint16, error) {
 99→	if n < 0 || n > math.MaxUint16 {
100→		return 0, fmt.Errorf("%w: %s 长度 %d 超出 uint16", ErrMalformed, what, n)
101→	}
102→	return uint16(n), nil
103→}
104→
105→// u32 安全地把 int 转成 uint32。
106→func u32(n int, what string) (uint32, error) {
107→	if n < 0 || uint64(n) > math.MaxUint32 {
108→		return 0, fmt.Errorf("%w: %s 长度 %d 超出 uint32", ErrMalformed, what, n)
109→	}
110→	return uint32(n), nil
111→}
112→

