func (c *rawClient) sessionSetup() error {
    // round1
    neg := (&auth.NegotiateMessage{Flags: c.negFlags()}).Marshal()
    req := &wire.SessionSetupRequest{SecurityBuffer: neg, SecurityMode: wire.NegotiateSigningEnabled}
    body, _ := req.Append(nil)
    h := wire.Header{Command: wire.CommandSessionSetup, Credits: 1, MessageID: c.nextMsgID(), SessionID: 0}
    reqMsg := h.Append(nil); reqMsg = append(reqMsg, body...)
    resp1, err := c.sendRaw(reqMsg, true)  // hash request
    if err != nil { return err }
    c.updatePreauth(resp1)  // hash intermediate response
    resp1Hdr, _ := wire.ParseHeader(resp1)
    // parse session setup response
    ssr, err := wire.ParseSessionSetupResponse(resp1)
    if err != nil { return err }
    challenge, err := auth.ParseChallengeMessage(ssr.SecurityBuffer)
    if err != nil { return err }
    c.sessionID = resp1Hdr.SessionID   // server assigned
    // round2
    authMsg := c.buildAuthenticate(challenge)
    req2 := &wire.SessionSetupRequest{SecurityBuffer: authMsg, SecurityMode: wire.NegotiateSigningEnabled}
    body2, _ := req2.Append(nil)
    h2 := wire.Header{Command: wire.CommandSessionSetup, Credits: 1, MessageID: c.nextMsgID(), SessionID: c.sessionID}
    reqMsg2 := h2.Append(nil); reqMsg2 = append(reqMsg2, body2...)
    resp2, err := c.sendRaw(reqMsg2, true)  // hash request 2
    if err != nil { return err }
    // NOT hash resp2 (final)
    resp2Hdr, _ := wire.ParseHeader(resp2)
    if resp2Hdr.Status != 0 { return fmt.Errorf("session setup failed: status %#x", resp2Hdr.Status) }
    ssr2, err := wire.ParseSessionSetupResponse(resp2)
    if err != nil { return err }
    // verify final response signature
    c.deriveKeys(ssr2)
    if err := crypto.Verify(uint16(c.dialect), c.signingKey, resp2); err != nil {
        return fmt.Errorf("session setup final response signature: %w", err)
    }
    if ssr2.SessionFlags & wire.SessionFlagEncryptData != 0 {
        c.encrypted = true
    }
    c.sessionEstablished = true
    return nil
}
```

