func (c *rawClient) buildAuthenticate(ch *auth.ChallengeMessage) []byte {
    ntHash := auth.NTHash(c.pass)
    ntowf := auth.NTOWFv2(ntHash, c.user, c.domain)
    // blob
    var blob bytes.Buffer
    blob.WriteByte(0x01) // RespType
    blob.WriteByte(0x01) // HiRespType
    blob.Write([]byte{0,0}) // Reserved
    blob.Write([]byte{0,0,0,0}) // Reserved
    ts := filetimeNow()
    blob.Write(ts[:])
    cc := make([]byte, 8); rand.Read(cc)
    blob.Write(cc)
    blob.Write([]byte{0,0,0,0}) // Reserved
    blob.Write(ch.TargetInfo.Encode())
    b := blob.Bytes()
    proof := auth.ComputeNTProofStr(ntowf, ch.ServerChallenge, b)
    var ntResp []byte
    ntResp = append(ntResp, proof[:]...)
    ntResp = append(ntResp, b...)
    sbk := auth.SessionBaseKey(ntowf, proof)
    // no KEY_EXCH: sessionKey = sbk
    c.sessionKey = sbk[:]
    msg := &auth.AuthenticateMessage{
        LMResponse: cc,  // LMv2-style: just client challenge
        NTResponse: ntResp,
        DomainName: c.domain,
        UserName: c.user,
        Workstation: "QA",
        EncryptedRandomSessionKey: nil,
        Flags: auth.NegotiateUnicode | auth.NegotiateRequestTarget | auth.NegotiateNTLM | auth.NegotiateExtendedSessionSecurity | auth.NegotiateTargetInfo | auth.NegotiateAlwaysSign | auth.Negotiate128 | auth.NegotiateVersion | auth.NegotiateTargetTypeServer | auth.NegotiateSign,
        Version: auth.Version{Major: 6, Minor: 1, Build: 7601, NTLMRevision: 15},
    }
    return msg.Marshal()
}
