		t.Fatalf("CANCEL 竟产生了响应（违反 §3.3.5.16）")
	}

	// 连接仍健康：后续 ECHO 应正常返回。
	if err := c.echo(); err != nil {
		t.Fatalf("CANCEL 后连接不可用（credit/连接被破坏？）: %v", err)
	}
